(window.webpackJsonp=window.webpackJsonp||[]).push([[17],{110:function(e){e.exports=JSON.parse('{"metadata":{"timed":true,"story ID":"b3e8e6f6-6a5c-4c66-9a57-bca850c45b19","title":{"_default":"AAHP-620-John-Bonaparte-9-21-2018"},"media":{"audio":"","video":"https://www.youtube.com/watch?v=uq-URSZLxM4"},"languages":[],"date_created":"","date_uploaded":"3/21/2026","source":{"_default":""},"description":"","genre":"","author":"","glosser":"","speakers":["Kendriana Drayton","John Bonaparte","Unknown"],"xml_file_name":"AAHP-620-John-Bonaparte-9-21-2018.eaf","source_filetype":"ELAN","tier IDs":{"Kendriana Drayton":{"subdivided":false},"John Bonaparte":{"subdivided":false},"Unknown":{"subdivided":false}},"speaker IDs":{"S1":{"name":"Kendriana Drayton","tier":"Kendriana Drayton"},"S2":{"name":"John Bonaparte","tier":"John Bonaparte"},"S3":{"name":"Unknown","tier":"Unknown"}}},"sentences":[{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1000,"end_time_ms":16000,"num_slots":1,"text":"All right. I\'m Kenna Drayton with the Oral History Program at the University of Florida. I\'m here with Mr. John Bona Park. I\'m gonna go ahead and allow him to introduce himself. You say your name, say your name.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":16000,"end_time_ms":19000,"num_slots":1,"text":"My name is John Bona Park.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":19000,"end_time_ms":22000,"num_slots":1,"text":"Okay. And where were you born?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":22000,"end_time_ms":26000,"num_slots":1,"text":"Born in South Carolina.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":26000,"end_time_ms":27000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":27000,"end_time_ms":30000,"num_slots":1,"text":"Okay. August.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":30000,"end_time_ms":35000,"num_slots":1,"text":"Um, were you born by a midwife or in a hospital?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":35000,"end_time_ms":36000,"num_slots":1,"text":"A hospital.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":36000,"end_time_ms":39000,"num_slots":1,"text":"At a hospital. What\'s your birthdate?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":39000,"end_time_ms":43000,"num_slots":1,"text":"I was twenty eight, nineteen twenty six.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":43000,"end_time_ms":48000,"num_slots":1,"text":"Okay. Um, when you were growing up, did you have any family members in the military?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":48000,"end_time_ms":52000,"num_slots":1,"text":"No, uh, I had a grandfather. Uncle.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":52000,"end_time_ms":53000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":53000,"end_time_ms":58000,"num_slots":1,"text":"Two uncles.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":58000,"end_time_ms":59000,"num_slots":1,"text":"You know what branches they served in","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":59000,"end_time_ms":60000,"num_slots":1,"text":"Army?","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":60000,"end_time_ms":67000,"num_slots":1,"text":"No. Army. Okay. Do you remember when you first heard about the war?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":67000,"end_time_ms":73000,"num_slots":1,"text":"Yes, I did. I didn\'t think I\'d make it","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":73000,"end_time_ms":75000,"num_slots":1,"text":"<laugh>. What? Make it to the war or from","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":75000,"end_time_ms":77000,"num_slots":1,"text":"I didn\'t think I\'d get it to the war.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":77000,"end_time_ms":87000,"num_slots":1,"text":"<laugh>. Okay. You thought it\'d be over? Hopefully. Yeah. Yeah. And so you said you were drafted?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":87000,"end_time_ms":89000,"num_slots":1,"text":"I was drafted, yeah. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":89000,"end_time_ms":92000,"num_slots":1,"text":"What was that like?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":92000,"end_time_ms":95000,"num_slots":1,"text":"Frightening.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":95000,"end_time_ms":97000,"num_slots":1,"text":"What\'d you do?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":97000,"end_time_ms":100000,"num_slots":1,"text":"Well, I just, just went.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":100000,"end_time_ms":106000,"num_slots":1,"text":"Okay. Did they give you much notice time to pack and get ready?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":106000,"end_time_ms":108000,"num_slots":1,"text":"Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":108000,"end_time_ms":111000,"num_slots":1,"text":"Okay. Where did you have to report to?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":111000,"end_time_ms":115000,"num_slots":1,"text":"Uh, <inaudible> Road.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":115000,"end_time_ms":117000,"num_slots":1,"text":"So Stark area?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":117000,"end_time_ms":118000,"num_slots":1,"text":"Yes.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":118000,"end_time_ms":121000,"num_slots":1,"text":"Okay. About how long was your training?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":121000,"end_time_ms":124000,"num_slots":1,"text":"About a week.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":124000,"end_time_ms":127000,"num_slots":1,"text":"What\'d you do?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":127000,"end_time_ms":130000,"num_slots":1,"text":"They, uh, I examined.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":130000,"end_time_ms":131000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":131000,"end_time_ms":135000,"num_slots":1,"text":"Interviewed you and got you ready.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":135000,"end_time_ms":139000,"num_slots":1,"text":"All right. And that training, did you learn how to operate a gun?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":139000,"end_time_ms":140000,"num_slots":1,"text":"Yes.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":140000,"end_time_ms":142000,"num_slots":1,"text":"In a week?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":142000,"end_time_ms":156000,"num_slots":1,"text":"No. Uh, this was, this was, uh, orientation, you know, cup, uh, they were for getting you ready to be enlisted into the Navy.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":156000,"end_time_ms":162000,"num_slots":1,"text":"Okay. So you selected the Navy?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":162000,"end_time_ms":171000,"num_slots":1,"text":"I wanted the Army. I wanted the Army, but they, they told me, uh, the Navy needed me. Okay. So I joined the Navy.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":171000,"end_time_ms":180000,"num_slots":1,"text":"So you kind of had to go where you were needed. Yeah. Um, so what was your impression of the Navy? Was it what you thought it would be? Well,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":180000,"end_time_ms":189000,"num_slots":1,"text":"The Navy, I, I didn\'t, I didn\'t want, I didn\'t want to be on <laugh>, on the ground with the Army.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":189000,"end_time_ms":190000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":190000,"end_time_ms":195000,"num_slots":1,"text":"So I chose the Navy.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":195000,"end_time_ms":198000,"num_slots":1,"text":"So where did you go?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":198000,"end_time_ms":204000,"num_slots":1,"text":"My first trip was Kovi, Iceland.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":204000,"end_time_ms":207000,"num_slots":1,"text":"How long were you there?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":207000,"end_time_ms":211000,"num_slots":1,"text":"Uh, about two days.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":211000,"end_time_ms":214000,"num_slots":1,"text":"When did you learn you were going to Iceland?","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":214000,"end_time_ms":215000,"num_slots":1,"text":"Uh,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":215000,"end_time_ms":219000,"num_slots":1,"text":"Uh, I, I didn\'t know until we got there.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":219000,"end_time_ms":221000,"num_slots":1,"text":"I\'m surprised.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":221000,"end_time_ms":223000,"num_slots":1,"text":"<laugh>.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":223000,"end_time_ms":225000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":225000,"end_time_ms":228000,"num_slots":1,"text":"Did you have to fight there?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":228000,"end_time_ms":236000,"num_slots":1,"text":"No. We, we, we was on a supply shift. Okay. We carried food.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":236000,"end_time_ms":241000,"num_slots":1,"text":"Did you get to interact with any of the locals?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":241000,"end_time_ms":242000,"num_slots":1,"text":"No.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":242000,"end_time_ms":244000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":244000,"end_time_ms":249000,"num_slots":1,"text":"So your job at Iceland was to prep things?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":249000,"end_time_ms":271000,"num_slots":1,"text":"It was, uh, uh, we, we, we were, we, we carried food from, from different countries. You know, we, we, uh, we load up in Beon, New Jersey, and then we\'d take a trip to a foreign country.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":271000,"end_time_ms":272000,"num_slots":1,"text":"Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":272000,"end_time_ms":282000,"num_slots":1,"text":"So my first trip was Iceland. The second trip was New Holland, attention","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":282000,"end_time_ms":283000,"num_slots":1,"text":"Newling.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":283000,"end_time_ms":303000,"num_slots":1,"text":"And then, uh, we took a trip about every month. Okay. So we\'d go at Guantanamo Bay, and, uh, we was, uh, and have a Havana and different islands and, and Puerto Rico. In","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":303000,"end_time_ms":304000,"num_slots":1,"text":"Puerto Rico.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":304000,"end_time_ms":306000,"num_slots":1,"text":"Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":306000,"end_time_ms":314000,"num_slots":1,"text":"Was it different in those different islands? Was the interactions different there than when you got back to the us?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":314000,"end_time_ms":332000,"num_slots":1,"text":"No, they islands are, you know, islands were mostly tourist. You know, most of \'em was tourist islands, but they had, uh, they had bases there, you know, army, navy bases and island. Okay. We supplied them with food.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":332000,"end_time_ms":334000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":334000,"end_time_ms":341000,"num_slots":1,"text":"While you were traveling and serving in the service, did you keep in close touch with your family?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":341000,"end_time_ms":365000,"num_slots":1,"text":"Oh, yes. Mm-hmm <affirmative>. Yeah. When we came in, we, we, we came into, uh, the port. If you can afford it, you could go home, because it took about 15 days to load up, you know? And, uh, and then we\'d take another trip.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":365000,"end_time_ms":368000,"num_slots":1,"text":"So how would you contact your family?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":368000,"end_time_ms":376000,"num_slots":1,"text":"Well, I, I usually took the train and come home.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":376000,"end_time_ms":378000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":378000,"end_time_ms":385000,"num_slots":1,"text":"Did you serve along with different races of people with white, with Asian?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":385000,"end_time_ms":398000,"num_slots":1,"text":"Yeah. We had, we had, we had a white crew across from our compartment. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":398000,"end_time_ms":400000,"num_slots":1,"text":"And tell me more about that.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":400000,"end_time_ms":407000,"num_slots":1,"text":"We just, we just like one big happy family, really.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":407000,"end_time_ms":412000,"num_slots":1,"text":"So what was a typical day like on the ship?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":412000,"end_time_ms":424000,"num_slots":1,"text":"Uh, typical day, we had mo we had movie. We had plenty of food because we haul food. We didn\'t worry about starving.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":424000,"end_time_ms":435000,"num_slots":1,"text":"Okay. What kind of food you eat?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":435000,"end_time_ms":446000,"num_slots":1,"text":"Well, uh, mostly we carried, we carried every, we carried all type of foods, food, steaks, <laugh>,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":446000,"end_time_ms":447000,"num_slots":1,"text":"Favorite.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":447000,"end_time_ms":455000,"num_slots":1,"text":"Yeah, plenty of oranges, potatoes, <laugh>. <laugh>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":455000,"end_time_ms":460000,"num_slots":1,"text":"Okay. Are you, were you a, did you cook any of the food? Were you cook?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":460000,"end_time_ms":463000,"num_slots":1,"text":"Yeah, Uhhuh. <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":463000,"end_time_ms":470000,"num_slots":1,"text":"So what were some of your duties besides transporting the food?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":470000,"end_time_ms":491000,"num_slots":1,"text":"Uh, our duties. Our duties, uh, what we did, uh, we, we had, we had, uh, battle, regular battle stations, practice, you know, if, you know, if we had any action, you know, we, we had battle stations to go","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":491000,"end_time_ms":494000,"num_slots":1,"text":"To, to practice. Yeah. So there were drills.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":494000,"end_time_ms":506000,"num_slots":1,"text":"Yeah. Drill and operate, you know, operate, uh, guns and aircraft, guns.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":506000,"end_time_ms":513000,"num_slots":1,"text":"Did you all have to use separate equipment? Was there segregation within the units?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":513000,"end_time_ms":520000,"num_slots":1,"text":"Yes, it was segregation. Sure.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":520000,"end_time_ms":525000,"num_slots":1,"text":"<affirmative>. So was that any different from home?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":525000,"end_time_ms":526000,"num_slots":1,"text":"Yes. A bit different? Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":526000,"end_time_ms":527000,"num_slots":1,"text":"Oh,","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":527000,"end_time_ms":548000,"num_slots":1,"text":"Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":548000,"end_time_ms":552000,"num_slots":1,"text":"How is it different?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":552000,"end_time_ms":577000,"num_slots":1,"text":"Uh, well, well, well, you were, you were, you were closer to different people when you were on the ship and in home. You could separate yourself. See, we had to, we had to, we had to be around different people.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":577000,"end_time_ms":583000,"num_slots":1,"text":"How was that?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":583000,"end_time_ms":600000,"num_slots":1,"text":"Segregation. Segregation. <laugh>. This was a time, this was a time when they had white and black faucets. Mm-hmm <affirmative>. And, and, uh, places where white blacks couldn\'t go, you know?","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":600000,"end_time_ms":602000,"num_slots":1,"text":"That was at home.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":602000,"end_time_ms":605000,"num_slots":1,"text":"It was home and, and, and avoid ship too.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":605000,"end_time_ms":611000,"num_slots":1,"text":"Okay. But you still served?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":611000,"end_time_ms":617000,"num_slots":1,"text":"Yeah, sure. We served together. Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":617000,"end_time_ms":620000,"num_slots":1,"text":"But still reminded of segregation,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":620000,"end_time_ms":632000,"num_slots":1,"text":"<laugh>, but remind you. Mm-hmm <affirmative>. <laugh>. Let\'s see. It still, still need to be corrected","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":632000,"end_time_ms":633000,"num_slots":1,"text":"Even now.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":633000,"end_time_ms":640000,"num_slots":1,"text":"Right? Now.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":640000,"end_time_ms":645000,"num_slots":1,"text":"So you were saying like, when you would come home, you could separate yourself?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":645000,"end_time_ms":646000,"num_slots":1,"text":"Oh, yes. Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":646000,"end_time_ms":648000,"num_slots":1,"text":"Was that more comfortable?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":648000,"end_time_ms":658000,"num_slots":1,"text":"Yes. Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":658000,"end_time_ms":671000,"num_slots":1,"text":"Okay. So can we, we rewind a little bit. So like, maybe right before you enlisted, we gonna go back a little bit, okay? Mm-hmm <affirmative>. So did you go to high school?","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":671000,"end_time_ms":673000,"num_slots":1,"text":"Mm-hmm <affirmative>. Where?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":673000,"end_time_ms":675000,"num_slots":1,"text":"Jacksonville","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":675000,"end_time_ms":681000,"num_slots":1,"text":"Graduated. Yeah. What high school?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":681000,"end_time_ms":683000,"num_slots":1,"text":"Stanton.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":683000,"end_time_ms":689000,"num_slots":1,"text":"Stanton. How did you get to school? Every day?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":689000,"end_time_ms":690000,"num_slots":1,"text":"Walk.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":690000,"end_time_ms":692000,"num_slots":1,"text":"How long was you walk?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":692000,"end_time_ms":695000,"num_slots":1,"text":"About five miles a day.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":695000,"end_time_ms":700000,"num_slots":1,"text":"Two and four. To, to get there and to get back home?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":700000,"end_time_ms":706000,"num_slots":1,"text":"Yeah. That\'s 10 miles. <laugh>. That\'s 10 miles. <laugh>.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":706000,"end_time_ms":710000,"num_slots":1,"text":"<laugh>. Wow.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":710000,"end_time_ms":717000,"num_slots":1,"text":"Wow. Who are your teachers? Or do you ha did you have any favorite teachers?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":717000,"end_time_ms":742000,"num_slots":1,"text":"Yeah, I have a favorite teacher. I had one teacher, <laugh>. I had, uh, my first grade teacher. Mm-hmm <affirmative>. When I came outta the service, I went to St. Augustine, the college on a trade. Mm-hmm <affirmative>. And my first grade teacher was there trying to get her other two years <laugh>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":742000,"end_time_ms":745000,"num_slots":1,"text":"So she was still getting some schooling too.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":745000,"end_time_ms":766000,"num_slots":1,"text":"Uh, she was there trying to, trying to get her four years. Mm-hmm <affirmative>. They allowed them to teach black teachers to teach two years at that time. And I was surprised to see my first grade teachers <laugh> from meeting her in college. <laugh>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":766000,"end_time_ms":769000,"num_slots":1,"text":"So what college was in St. Augustine?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":769000,"end_time_ms":774000,"num_slots":1,"text":"It was a Florida normal <laugh>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":774000,"end_time_ms":777000,"num_slots":1,"text":"It tickles you. <laugh>. She","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":777000,"end_time_ms":779000,"num_slots":1,"text":"Really did.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":779000,"end_time_ms":783000,"num_slots":1,"text":"But in a good way. Right? It was like good to see her still going. Yeah. Well,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":783000,"end_time_ms":784000,"num_slots":1,"text":"I, I, I was surprised","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":784000,"end_time_ms":785000,"num_slots":1,"text":"Too. Uhhuh <affirmative>.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":785000,"end_time_ms":788000,"num_slots":1,"text":"You see her?","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":788000,"end_time_ms":796000,"num_slots":1,"text":"Okay. So did you hope to go to college after school, or were you thinking","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":796000,"end_time_ms":803000,"num_slots":1,"text":"Of arms? Yeah, I, I intend to go to college because, uh, my high school years I was, I was a printer.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":803000,"end_time_ms":804000,"num_slots":1,"text":"A printer? Yeah.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":804000,"end_time_ms":807000,"num_slots":1,"text":"I learned, I learned to be a printer.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":807000,"end_time_ms":808000,"num_slots":1,"text":"Newspaper. Printer.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":808000,"end_time_ms":825000,"num_slots":1,"text":"Yeah. Newspaper printer. Yeah. And I worked as a printer. I, I was sent, I was sent to this job by the government to work as a printer.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":825000,"end_time_ms":827000,"num_slots":1,"text":"When? Around when,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":827000,"end_time_ms":891000,"num_slots":1,"text":"So after, after I work, worked with this, this white guy. Mm-hmm <affirmative>. He <laugh>, he, he, he, he came up to my work with him five years <affirmative>. And, uh, and this, this was under the, under the government. And, uh, when, when he, he, uh, got a job. He, he, he got, he got a job at a big newspaper company. Mm-hmm <affirmative>. In Palka. He came up to me one day and said, uh, I was out of a job. So he didn\'t, he didn\'t want to trust me, you know? Mm-hmm <affirmative>. With him. Evidently, I, I think, I think I knew more than he did, but he got his job. <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":891000,"end_time_ms":894000,"num_slots":1,"text":"So after that, you stopped working in printing?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":894000,"end_time_ms":913000,"num_slots":1,"text":"So after that, <laugh>, I, I <laugh>, he didn\'t know I was a carpenter, so I went in, I went into the building trade. I worked, I worked the company for 20 years","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":913000,"end_time_ms":914000,"num_slots":1,"text":"As a carpenter.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":914000,"end_time_ms":921000,"num_slots":1,"text":"Mm-hmm <affirmative>. I worked for myself for about 10 years when I retired.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":921000,"end_time_ms":925000,"num_slots":1,"text":"And what, where did you do most of your work?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":925000,"end_time_ms":932000,"num_slots":1,"text":"<inaudible> what? Putnam County.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":932000,"end_time_ms":943000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":943000,"end_time_ms":953000,"num_slots":1,"text":"So you talked about your uncles serving in the service in the Army. Were anyone in your family a part of like the Masons or any other organizations?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":953000,"end_time_ms":959000,"num_slots":1,"text":"Yeah, two uncles. Was Mason.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":959000,"end_time_ms":964000,"num_slots":1,"text":"Did that intrigue you? Did that interest you?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":964000,"end_time_ms":977000,"num_slots":1,"text":"Oh, yes. Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":977000,"end_time_ms":984000,"num_slots":1,"text":"So did you vote before you were enlisted, or when did you first vote?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":984000,"end_time_ms":991000,"num_slots":1,"text":"I voted after, after I came back from the service.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":991000,"end_time_ms":994000,"num_slots":1,"text":"And that was around what time?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":994000,"end_time_ms":1000000,"num_slots":1,"text":"It was, uh, it was in 1947.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":1000000,"end_time_ms":1006000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1006000,"end_time_ms":1011000,"num_slots":1,"text":"What was the community like when you came back home?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1011000,"end_time_ms":1016000,"num_slots":1,"text":"Uh, the community was actually the same.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1016000,"end_time_ms":1017000,"num_slots":1,"text":"Changed.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1017000,"end_time_ms":1020000,"num_slots":1,"text":"We needed improvement.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1020000,"end_time_ms":1022000,"num_slots":1,"text":"So after still fighting?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1022000,"end_time_ms":1025000,"num_slots":1,"text":"Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1025000,"end_time_ms":1040000,"num_slots":1,"text":"Okay. Can you tell us about your voting experience? Was there like any hardships in going to do it?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1040000,"end_time_ms":1058000,"num_slots":1,"text":"No. No hardships. And I have my choices when I do vote.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1058000,"end_time_ms":1061000,"num_slots":1,"text":"Did you ever hear about your parents talking about voting?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1061000,"end_time_ms":1062000,"num_slots":1,"text":"Oh, yeah. Mm-hmm","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":1062000,"end_time_ms":1063000,"num_slots":1,"text":"<affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1063000,"end_time_ms":1065000,"num_slots":1,"text":"Did they talk about what it meant to them?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1065000,"end_time_ms":1078000,"num_slots":1,"text":"Sure. Yes.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1078000,"end_time_ms":1086000,"num_slots":1,"text":"Well, what kind of changes have you seen since you\'ve been here, right? You came back to Crescent City?","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":1086000,"end_time_ms":1090000,"num_slots":1,"text":"<laugh>.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1090000,"end_time_ms":1092000,"num_slots":1,"text":"It hasn\'t been much change.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":1092000,"end_time_ms":1096000,"num_slots":1,"text":"I,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1096000,"end_time_ms":1100000,"num_slots":1,"text":"I don\'t think desegregation changed anything.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1100000,"end_time_ms":1103000,"num_slots":1,"text":"No, I don\'t think so.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":1103000,"end_time_ms":1120000,"num_slots":1,"text":"Hmm.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1120000,"end_time_ms":1133000,"num_slots":1,"text":"You say you were born in South Carolina? Yeah. Do you know if you had any, um, ancestors or family members that served in the government? As far as like politicians or","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1133000,"end_time_ms":1134000,"num_slots":1,"text":"No. No.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1134000,"end_time_ms":1147000,"num_slots":1,"text":"Okay. What about slaves? Anyone enslaved? Did you hear about your parents or grandparents talk about slavery?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1147000,"end_time_ms":1153000,"num_slots":1,"text":"Yes. My grandmother used to talk about it.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":1153000,"end_time_ms":1158000,"num_slots":1,"text":"Mm-hmm <affirmative>. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1158000,"end_time_ms":1160000,"num_slots":1,"text":"Is she from South Carolina?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1160000,"end_time_ms":1161000,"num_slots":1,"text":"Yes. Mm-hmm","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":1161000,"end_time_ms":1163000,"num_slots":1,"text":"<affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1163000,"end_time_ms":1165000,"num_slots":1,"text":"You know her name? Remember her name?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1165000,"end_time_ms":1169000,"num_slots":1,"text":"Rachel. Rachel. Really?","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1169000,"end_time_ms":1170000,"num_slots":1,"text":"Really?","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":1170000,"end_time_ms":1181000,"num_slots":1,"text":"Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1181000,"end_time_ms":1190000,"num_slots":1,"text":"So what kind of changes did you notice during desegregation? Which would be about the seventies?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1190000,"end_time_ms":1191000,"num_slots":1,"text":"About the seventies?","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":1191000,"end_time_ms":1194000,"num_slots":1,"text":"Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1194000,"end_time_ms":1212000,"num_slots":1,"text":"Uh, well, it, it\'s, it\'s, it\'s been a change, but it, it, it, it needs it, it needs to be better, you know? It\'s, it\'s, it\'s been a little change.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1212000,"end_time_ms":1218000,"num_slots":1,"text":"Better, like how you said it a few times, but it hasn\'t changed much. No,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1218000,"end_time_ms":1231000,"num_slots":1,"text":"It hasn\'t changed much. Now. Seems like we\'re going backwards now.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1231000,"end_time_ms":1237000,"num_slots":1,"text":"Do you feel like family is still really important? Was that a important part?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1237000,"end_time_ms":1249000,"num_slots":1,"text":"Sure. Uh,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1249000,"end_time_ms":1261000,"num_slots":1,"text":"Okay. So let\'s go back to Florida normal. Mm-hmm <affirmative>. How did you get to college every day? Or how often did you go?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1261000,"end_time_ms":1262000,"num_slots":1,"text":"Every day? I had a,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1262000,"end_time_ms":1263000,"num_slots":1,"text":"Every","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1263000,"end_time_ms":1264000,"num_slots":1,"text":"Day I had a car.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1264000,"end_time_ms":1269000,"num_slots":1,"text":"Okay. What kind of car?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1269000,"end_time_ms":1278000,"num_slots":1,"text":"We lived off campus. Uh, uh, I had a, a Ford car. A Ford","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1278000,"end_time_ms":1280000,"num_slots":1,"text":"Car.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1280000,"end_time_ms":1290000,"num_slots":1,"text":"We, we lived off campus. We had a, we, we rented a house, and I had a house and rent.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1290000,"end_time_ms":1295000,"num_slots":1,"text":"How much is rent?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1295000,"end_time_ms":1298000,"num_slots":1,"text":"About, about 75. All of a month.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1298000,"end_time_ms":1301000,"num_slots":1,"text":"And you worked as a printer to pay the rent?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1301000,"end_time_ms":1302000,"num_slots":1,"text":"Yes. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1302000,"end_time_ms":1309000,"num_slots":1,"text":"Okay. So what was your college day like?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1309000,"end_time_ms":1310000,"num_slots":1,"text":"What was it like? Mm-hmm","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1310000,"end_time_ms":1313000,"num_slots":1,"text":"<affirmative>. What\'d you do?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1313000,"end_time_ms":1344000,"num_slots":1,"text":"Oh, uh, we had classes and, and, uh, and, uh, I, I worked at the, uh, I, I did the, the college, you know, the college letterheads and all, all of their, all the, uh, all of their, uh, graphic, you know, papers Okay. To use envelopes. And, uh, their business, business letter, you know, I, I printed those.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1344000,"end_time_ms":1357000,"num_slots":1,"text":"Okay. Did you have any, uh, like white professors or any white staff at the school?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1357000,"end_time_ms":1369000,"num_slots":1,"text":"Yeah, I had, I had two, uh, two white, uh, teachers. And, uh, this, this school was a predominantly black college.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1369000,"end_time_ms":1375000,"num_slots":1,"text":"Okay. So most of your teachers are black?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1375000,"end_time_ms":1377000,"num_slots":1,"text":"Yeah, most of \'em are black.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1377000,"end_time_ms":1381000,"num_slots":1,"text":"Okay. What other kind of things did they have at the college?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1381000,"end_time_ms":1401000,"num_slots":1,"text":"It was, uh, an agriculture college too. They raised different type of stocks, you know, uh, cows and, uh, you know, sheep, goats, ducks, <laugh>,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1401000,"end_time_ms":1404000,"num_slots":1,"text":"Some of everything.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1404000,"end_time_ms":1409000,"num_slots":1,"text":"And more or less in the industrial cottage.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1409000,"end_time_ms":1413000,"num_slots":1,"text":"Okay. Well, why did you choose there?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1413000,"end_time_ms":1425000,"num_slots":1,"text":"Well, they, they, uh, they, uh, the, the government, you know, it, it was close, I think. And they, and they, uh, had that, they had that particular trade.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1425000,"end_time_ms":1428000,"num_slots":1,"text":"Okay. See the degree you wanted?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1428000,"end_time_ms":1436000,"num_slots":1,"text":"Yeah. I could have gone to Daytona or someplace like that, you know? Mm-hmm <affirmative>. But that was close.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1436000,"end_time_ms":1441000,"num_slots":1,"text":"And think about like, trying to integrate a white college.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1441000,"end_time_ms":1451000,"num_slots":1,"text":"Yeah. It, it, it, it wouldn\'t have made any difference because I just met the wrong man. Hmm. When I was, when I, when I was, you know, in my profession.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1451000,"end_time_ms":1454000,"num_slots":1,"text":"What do you mean,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1454000,"end_time_ms":1458000,"num_slots":1,"text":"<laugh>? I met the, I met the wrong, I worked with the wrong person.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1458000,"end_time_ms":1476000,"num_slots":1,"text":"Oh, that guy. Yeah. Okay. Well, I think we got, um, pretty good details. So just to kind of wrap this up, were there any other times that you served in the military?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1476000,"end_time_ms":1477000,"num_slots":1,"text":"No. Uhuh? No.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1477000,"end_time_ms":1482000,"num_slots":1,"text":"And the highest rank, you said you, you were","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1482000,"end_time_ms":1483000,"num_slots":1,"text":"First class,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1483000,"end_time_ms":1489000,"num_slots":1,"text":"First class, mm-hmm <affirmative>. And you didn\'t receive or sustain any injuries during your service? No.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1489000,"end_time_ms":1490000,"num_slots":1,"text":"No.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1490000,"end_time_ms":1493000,"num_slots":1,"text":"Is there anything else you\'d like to add?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1493000,"end_time_ms":1499000,"num_slots":1,"text":"I was in A VFW for 35 years.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1499000,"end_time_ms":1502000,"num_slots":1,"text":"V-M-W-V-F-W. What is that?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1502000,"end_time_ms":1504000,"num_slots":1,"text":"Veteran Park War.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1504000,"end_time_ms":1505000,"num_slots":1,"text":"Where, where was that? It\'s","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1505000,"end_time_ms":1507000,"num_slots":1,"text":"A club in C City.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1507000,"end_time_ms":1512000,"num_slots":1,"text":"What kind of things did you all do? Hmm. What kind of things did you all do when you first started?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1512000,"end_time_ms":1535000,"num_slots":1,"text":"Uh, um, we served the, the community, you know, different. It is what it is, is an organization. The VFW is an organization. Mm-hmm <affirmative>. For the vfw for the veterans. And what they do, they, uh, give out scholarships and, you know, and stuff like that for","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1535000,"end_time_ms":1536000,"num_slots":1,"text":"The students.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1536000,"end_time_ms":1538000,"num_slots":1,"text":"Students, yeah. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1538000,"end_time_ms":1540000,"num_slots":1,"text":"Okay. Do you all have a meeting place?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1540000,"end_time_ms":1542000,"num_slots":1,"text":"Yeah. Meeting place? Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1542000,"end_time_ms":1546000,"num_slots":1,"text":"So it\'s a building or a large, somewhere around Scent City? Yeah.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1546000,"end_time_ms":1547000,"num_slots":1,"text":"Uhhuh. <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1547000,"end_time_ms":1550000,"num_slots":1,"text":"Okay. Um, how did you join?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1550000,"end_time_ms":1572000,"num_slots":1,"text":"Uh, I just, uh, uh, I was asked to join by one of the members back in 19 40, 19. Uh, lemme see. 40, 19 70, 19 75. Yeah, I\'ve been in it since 1975.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1572000,"end_time_ms":1576000,"num_slots":1,"text":"Over the years. Has there been more blacks?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1576000,"end_time_ms":1577000,"num_slots":1,"text":"Yes. Uhhuh. <affirmative>,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1577000,"end_time_ms":1578000,"num_slots":1,"text":"Yeah. More black soldiers to join?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1578000,"end_time_ms":1588000,"num_slots":1,"text":"Yeah. Mm-hmm <affirmative>. We had quite a few blacks in there. And I was in the Lion Club for six years.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1588000,"end_time_ms":1591000,"num_slots":1,"text":"So you got a part of different community organizations? Yeah. That","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1591000,"end_time_ms":1593000,"num_slots":1,"text":"Was community? Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1593000,"end_time_ms":1594000,"num_slots":1,"text":"Why?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1594000,"end_time_ms":1600000,"num_slots":1,"text":"Well, to help people in the community.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":1600000,"end_time_ms":1604000,"num_slots":1,"text":"Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1604000,"end_time_ms":1627000,"num_slots":1,"text":"And I was on the, um, the, uh, um, trade, uh, trades. Um, build, uh, build, um, trades. Trades, uh, at the high school.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1627000,"end_time_ms":1628000,"num_slots":1,"text":"Oh, at your high school? At Stanford","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1628000,"end_time_ms":1639000,"num_slots":1,"text":"High School? Yeah. It was a trade department. Mm-hmm <affirmative>. I was on there for seven to 17 years for high school.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1639000,"end_time_ms":1642000,"num_slots":1,"text":"So did you go and do work there, or you kind of just","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1642000,"end_time_ms":1651000,"num_slots":1,"text":"Well, we, we, uh, we, we were over the, over the kids that took different trades, you know, like Oh, okay. Mechanic and builders.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1651000,"end_time_ms":1652000,"num_slots":1,"text":"So did you all teach them?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1652000,"end_time_ms":1656000,"num_slots":1,"text":"Yeah. Yeah. We was instructor instructors.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1656000,"end_time_ms":1658000,"num_slots":1,"text":"So you worked as a teacher as well? We was","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1658000,"end_time_ms":1690000,"num_slots":1,"text":"An instructors. Mm-hmm <affirmative>. You know, we, what we do, we have meetings to keep it going. See, you\'re sponsored by the, the, the state, see, okay. But they, they, uh, they, they stopped for some reason. They don\'t have trades in the schools anymore, you know, not in this country, but they used to have the trades, different trades in mechanic. They used to have, um, building trade. Mm-hmm <affirmative>. They had, uh, the welding, auto, auto mechanic, you know, and stuff like that. But, but they don\'t have it anymore. See,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1690000,"end_time_ms":1692000,"num_slots":1,"text":"And that\'s a, that\'s a bad change.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1692000,"end_time_ms":1708000,"num_slots":1,"text":"And that\'s, that\'s one thing they need to have in, in these schools now. Then main thing, main thing is, and teach these kids, these women how to cook <laugh>, they need, they need that back in school. <laugh>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1708000,"end_time_ms":1713000,"num_slots":1,"text":"So we got some trades. Yeah. And home care that needs to be taken care. Yeah. Mm-hmm","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1713000,"end_time_ms":1724000,"num_slots":1,"text":"<affirmative>. So we are, I was in quite a few organizations.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1724000,"end_time_ms":1727000,"num_slots":1,"text":"So you still was being active even after","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1727000,"end_time_ms":1728000,"num_slots":1,"text":"Yeah. Uhhuh, <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1728000,"end_time_ms":1737000,"num_slots":1,"text":"You were out. Simons. Did you ever have any type of resistance from the white community?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1737000,"end_time_ms":1741000,"num_slots":1,"text":"No. They all all helped, you know?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1741000,"end_time_ms":1753000,"num_slots":1,"text":"Yeah. They all helped. You know, anything we got into, they, uh, they participated and, and, you know, help us going, you know, keep going.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1753000,"end_time_ms":1761000,"num_slots":1,"text":"Okay. So how did you land in Crescent City?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1761000,"end_time_ms":1770000,"num_slots":1,"text":"Uh, when I went into service, uh, my mother married a guy from this area.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1770000,"end_time_ms":1771000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1771000,"end_time_ms":1778000,"num_slots":1,"text":"And, uh, when I came out, they moved down here. So that\'s Crescent City, <laugh>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1778000,"end_time_ms":1788000,"num_slots":1,"text":"Okay. Do you know why they left South Carolina originally?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1788000,"end_time_ms":1791000,"num_slots":1,"text":"Uh, for better, better living.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1791000,"end_time_ms":1793000,"num_slots":1,"text":"So Florida was a, a good opportunity. Uh,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1793000,"end_time_ms":1810000,"num_slots":1,"text":"Most of my people moved. Most of my, most of my people moved from South Carolina to New York. Okay. All but my mother, she moved to Jacksonville, and that\'s where we were raised up in Jacksonville.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1810000,"end_time_ms":1813000,"num_slots":1,"text":"But you got to visit New York?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1813000,"end_time_ms":1815000,"num_slots":1,"text":"Yeah, quite a few times. Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1815000,"end_time_ms":1818000,"num_slots":1,"text":"How was traveling?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1818000,"end_time_ms":1831000,"num_slots":1,"text":"That\'s real nice. Most the time I flew and later years I drove. Hmm.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1831000,"end_time_ms":1838000,"num_slots":1,"text":"Did you have to kind of stop at certain places, like during segregation or could you kind of go","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1838000,"end_time_ms":1842000,"num_slots":1,"text":"It was straight, straight lighter, straight driving.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1842000,"end_time_ms":1843000,"num_slots":1,"text":"Oh. No stops. No","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1843000,"end_time_ms":1855000,"num_slots":1,"text":"Stops. <laugh>, unless, you know, for driving, we had to, you know, to stop motel one night.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1855000,"end_time_ms":1857000,"num_slots":1,"text":"It was just best to get done. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1857000,"end_time_ms":1860000,"num_slots":1,"text":"Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1860000,"end_time_ms":1872000,"num_slots":1,"text":"Okay. Well, your two years of service, did you have any reflections? Did you feel like No. Uhuh No. No. Just did what you, what you was told to do?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1872000,"end_time_ms":1879000,"num_slots":1,"text":"Good. Yeah. Everything was nice. I enjoyed a little time I was in there.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1879000,"end_time_ms":1881000,"num_slots":1,"text":"You gotta go a lot of places.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1881000,"end_time_ms":1888000,"num_slots":1,"text":"Yeah. A lot of places. Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1888000,"end_time_ms":1892000,"num_slots":1,"text":"And so after you were out, you didn\'t choose to sign up again, right?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1892000,"end_time_ms":1909000,"num_slots":1,"text":"Oh, no. Actually, I got out on, on points, see the war was over, see? Mm-hmm <affirmative>. And you had points. That\'s why, that\'s why I didn\'t stay in long. See, other than that, I could have resigned, you know? And, you know, made it crazy. And then I went on and retired.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1909000,"end_time_ms":1912000,"num_slots":1,"text":"And what war was this?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1912000,"end_time_ms":1913000,"num_slots":1,"text":"World War ii.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1913000,"end_time_ms":1923000,"num_slots":1,"text":"Okay. All right. Is there anything else you\'d like to add? <affirmative>,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1923000,"end_time_ms":1934000,"num_slots":1,"text":"I, I can say this. Uh, we, we, uh, we, we supplied the, uh, we supplied the corny with food. Mm-hmm","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1934000,"end_time_ms":1936000,"num_slots":1,"text":"<affirmative>.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1936000,"end_time_ms":1968000,"num_slots":1,"text":"That was, uh, uh, protecting the carrier that they signed the Peace treaty on. Oh, Japanese signed the Peace Treaty. Mm-hmm <affirmative>. The carrier that was in the convoy, you know, of the ships out in the Atlantic. We served the food to the ships, you know, it was Yeah. You know, protecting that carrier. Oh, wow. That\'s a little history. <laugh>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1968000,"end_time_ms":1972000,"num_slots":1,"text":"So you served the ships that were protecting that treaty?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1972000,"end_time_ms":1988000,"num_slots":1,"text":"Yeah, we was on the ship that supplied the convoy. See? Mm-hmm <affirmative>. It was Convoy Ships Protect. Mm-hmm <affirmative>. Protecting the carrier. So we supplied the ships, um, that was protecting the carrier with food.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":1988000,"end_time_ms":1993000,"num_slots":1,"text":"How was that kind of working with the different classes of, of certain people? Well, that","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":1993000,"end_time_ms":2002000,"num_slots":1,"text":"Was good. It was good. We got a chance to meet different type of people and different ships, you know? Mm-hmm <affirmative>. Learn the names of a lot of ships.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2002000,"end_time_ms":2005000,"num_slots":1,"text":"Did you learn to speak any different languages?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2005000,"end_time_ms":2026000,"num_slots":1,"text":"No, I never spoke any different language. I went to a lot of Spanish, uh, folks, but I never did speak any of their language. Okay. Because when I went to een, IEN, uh, I don\'t, I don\'t, I don\'t think it\'s any, any black people left.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2026000,"end_time_ms":2027000,"num_slots":1,"text":"So you were all the only one","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2027000,"end_time_ms":2062000,"num_slots":1,"text":"<laugh>? Yeah, we were. How was that? They looked at us like we was something different, you know, I went over there, <laugh>, Newland, there were no black people there. We out. Yeah. We go out, you know, different places. Mm-hmm <affirmative>. Uh, then we came back and started going to Bermuda, Trinidad, and then Cuba.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2062000,"end_time_ms":2065000,"num_slots":1,"text":"And you say you stayed about a month in each place?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2065000,"end_time_ms":2079000,"num_slots":1,"text":"Yeah, no, just about 10 days. Okay. Take longer to load up the ship than it did get them. They unload it. See.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2079000,"end_time_ms":2082000,"num_slots":1,"text":"Do you remember how much you got paid","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2082000,"end_time_ms":2088000,"num_slots":1,"text":"<laugh>? We never got over $150 a month.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2088000,"end_time_ms":2089000,"num_slots":1,"text":"So it was monthly pay. That\'s","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2089000,"end_time_ms":2091000,"num_slots":1,"text":"Monthly pay.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2091000,"end_time_ms":2094000,"num_slots":1,"text":"Did that cover your clothes?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2094000,"end_time_ms":2112000,"num_slots":1,"text":"Yeah, we, you know, we were issued our suicide things. Okay.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2112000,"end_time_ms":2118000,"num_slots":1,"text":"So you were pretty good health wise. You didn\'t really have to go to the doctor or anything while you were enlisted?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2118000,"end_time_ms":2126000,"num_slots":1,"text":"No, I was in good shape until I got older. <laugh>.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":2126000,"end_time_ms":2131000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2131000,"end_time_ms":2138000,"num_slots":1,"text":"Any other memorable things where you\'ve been with different places?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2138000,"end_time_ms":2142000,"num_slots":1,"text":"Places I don\'t remember. No.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2142000,"end_time_ms":2148000,"num_slots":1,"text":"The different things about the different places?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2148000,"end_time_ms":2161000,"num_slots":1,"text":"No, it\'s, uh, climate wise, you know, I, Iceland was a freezing place all the time.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2161000,"end_time_ms":2162000,"num_slots":1,"text":"Where?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2162000,"end_time_ms":2163000,"num_slots":1,"text":"Iceland.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2163000,"end_time_ms":2166000,"num_slots":1,"text":"Iceland. <laugh>. Being from Florida,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2166000,"end_time_ms":2176000,"num_slots":1,"text":"Puerto Rico, and Trinidad, it\'s hot all the time.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2176000,"end_time_ms":2178000,"num_slots":1,"text":"Did you swim?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2178000,"end_time_ms":2181000,"num_slots":1,"text":"Oh yeah. You had to be a swimmer,","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":2181000,"end_time_ms":2182000,"num_slots":1,"text":"Right?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2182000,"end_time_ms":2192000,"num_slots":1,"text":"<laugh>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2192000,"end_time_ms":2205000,"num_slots":1,"text":"All right. Do you still have any, um, of your medals or awards at home? Huh? Do you still have any of your medals or awards at home?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2205000,"end_time_ms":2209000,"num_slots":1,"text":"I wear, I wear them on my VFW cap.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":2209000,"end_time_ms":2212000,"num_slots":1,"text":"Okay.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2212000,"end_time_ms":2231000,"num_slots":1,"text":"I\'d like to get a picture of that. All right. Well, thank you. And then if you, um, would like to share anything else, we can do this again. Okay?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2231000,"end_time_ms":2232000,"num_slots":1,"text":"Yeah. All right.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2232000,"end_time_ms":2233000,"num_slots":1,"text":"All right.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2233000,"end_time_ms":2236000,"num_slots":1,"text":"I\'m all right now.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2236000,"end_time_ms":2238000,"num_slots":1,"text":"Hmm?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2238000,"end_time_ms":2241000,"num_slots":1,"text":"That paper tell you everything on","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2241000,"end_time_ms":2247000,"num_slots":1,"text":"Oh, the newspaper article? Yeah. Okay. Well, I\'ll look to that. All right. Well, thank you. Granddad. Mm-hmm","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":2247000,"end_time_ms":2255000,"num_slots":1,"text":"<affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2269000,"end_time_ms":2273000,"num_slots":1,"text":"He is a handyman.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":2275000,"end_time_ms":2277000,"num_slots":1,"text":"Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2277000,"end_time_ms":2282000,"num_slots":1,"text":"I guy that live out there, I wonder if he found him and just kept him from me or something.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2284000,"end_time_ms":2293000,"num_slots":1,"text":"I need to go out there one day and just talk to him. But that old guy sold the house. He left them there, and he bought them pictures, them part, see?","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2293000,"end_time_ms":2297000,"num_slots":1,"text":"Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2297000,"end_time_ms":2304000,"num_slots":1,"text":"I have pictures of everywhere I went and everything I took, I take, I take a picture sitting on the White House step.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2306000,"end_time_ms":2310000,"num_slots":1,"text":"Yeah, the White House. Sit, sitting on the White House there.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2312000,"end_time_ms":2317000,"num_slots":1,"text":"You couldn\'t get, you couldn\'t get there Now, <laugh>, you couldn\'t go in.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2317000,"end_time_ms":2319000,"num_slots":1,"text":"Were you invited by the president?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2319000,"end_time_ms":2337000,"num_slots":1,"text":"No. I, I was in Washington. In Washington, and I went to the White House, went to the White House, and took a picture sitting on, on the step. That was one picture I wanted, wanted to say, because everybody would dispute me if, if I said it. Mm-hmm","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2337000,"end_time_ms":2338000,"num_slots":1,"text":"<affirmative>.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2338000,"end_time_ms":2357000,"num_slots":1,"text":"You know, <laugh>, when I first, when I first took my train, I took my train in Maryland too, and see that ain\'t, that ain\'t far, you know, you could travel that a little bit.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2357000,"end_time_ms":2358000,"num_slots":1,"text":"Maryland","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2358000,"end_time_ms":2359000,"num_slots":1,"text":"And then, uh, yeah,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2359000,"end_time_ms":2361000,"num_slots":1,"text":"From Camp Blandon to Maryland,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2361000,"end_time_ms":2392000,"num_slots":1,"text":"I was, no, I was in, uh, no, I was, I, I took, uh, camp Blandon is where I, where I went to, uh, be Sea, see? So they sent me from there to, uh, they sent me from there to Annapolis, Maryland. That\'s where the Naval Academy is. I worked there for about a month, and then I left there and got on a ship.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2392000,"end_time_ms":2394000,"num_slots":1,"text":"And that was the Saturn?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2394000,"end_time_ms":2400000,"num_slots":1,"text":"Yeah. Mm-hmm <affirmative>. Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2400000,"end_time_ms":2403000,"num_slots":1,"text":"How was your lodging?","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":2403000,"end_time_ms":2405000,"num_slots":1,"text":"Hmm?","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2405000,"end_time_ms":2411000,"num_slots":1,"text":"How was your lodging? Did you have like a bed or cut or,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2411000,"end_time_ms":2414000,"num_slots":1,"text":"Oh, what, where, what that mm-hmm","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2414000,"end_time_ms":2427000,"num_slots":1,"text":"Yeah. We slept in bunks. Had three <laugh>. Three. Three bed. Bunks. <laugh>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2427000,"end_time_ms":2430000,"num_slots":1,"text":"Did you serve with some people from around here, or were they all new people?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2430000,"end_time_ms":2446000,"num_slots":1,"text":"No, I, I couldn\'t find, I found one guy from Florida, <laugh>, one guy from Florida. I didn\'t be able to find him yet since I came out. I\'m looking for him.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2446000,"end_time_ms":2448000,"num_slots":1,"text":"Remember his name?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2448000,"end_time_ms":2465000,"num_slots":1,"text":"Uh, Mond. Jimmy Monds. Jimmy Monds. Supposed to be here from <inaudible>. And, uh, lemme see on the other side of D land.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2465000,"end_time_ms":2467000,"num_slots":1,"text":"So kind of close. Okay.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":2467000,"end_time_ms":2468000,"num_slots":1,"text":"Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2468000,"end_time_ms":2471000,"num_slots":1,"text":"And kind of close dLAN, you said?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2471000,"end_time_ms":2489000,"num_slots":1,"text":"Yeah. He was somewhere about, around dLAN Lake <inaudible>. That\'s where,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2489000,"end_time_ms":2495000,"num_slots":1,"text":"So this is, what do you do now to pass your time?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2495000,"end_time_ms":2498000,"num_slots":1,"text":"I sit around the <laugh>.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2498000,"end_time_ms":2500000,"num_slots":1,"text":"Think you working?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2500000,"end_time_ms":2516000,"num_slots":1,"text":"Yeah. I,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2516000,"end_time_ms":2527000,"num_slots":1,"text":"All right. What would you encourage young black children to, to kind of grow up, to do, go to school or to look into the military, or?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2527000,"end_time_ms":2556000,"num_slots":1,"text":"Military is good now. If they pay good money, get, they stay there long enough, you know, they, they, they can get the education, you know, you know, most I have, uh, most kids, you know, when they come out school, try the military. Most of those men, both girls too,","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2556000,"end_time_ms":2558000,"num_slots":1,"text":"Saying there\'s some good opportunities.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2558000,"end_time_ms":2561000,"num_slots":1,"text":"Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2561000,"end_time_ms":2564000,"num_slots":1,"text":"What about doing things in the community?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2564000,"end_time_ms":2585000,"num_slots":1,"text":"Well, I get into some organization to help people in the community. Mm-hmm <affirmative>. They have, they have these organizations. They have a nine club now. They have a BW, uh, they got one or two little clubs uptown, you know.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2585000,"end_time_ms":2587000,"num_slots":1,"text":"Oh, the chess tutoring?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2587000,"end_time_ms":2591000,"num_slots":1,"text":"Yeah. They tutor","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2591000,"end_time_ms":2594000,"num_slots":1,"text":"A Philip Randolph. Yeah. Ch tutoring.","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2594000,"end_time_ms":2597000,"num_slots":1,"text":"Yeah.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2597000,"end_time_ms":2604000,"num_slots":1,"text":"Did you ever meet any civil rights figures? Did you ever meet any civil rights figures?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2604000,"end_time_ms":2608000,"num_slots":1,"text":"No. I never have.","dependents":[]},{"speaker":"S1","tier":"Kendriana Drayton","start_time_ms":2608000,"end_time_ms":2610000,"num_slots":1,"text":"Or participate in any protests?","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2610000,"end_time_ms":2630000,"num_slots":1,"text":"No. No. They had little clubs, things around there. They got these boys to men and, you know,","dependents":[]},{"speaker":"S2","tier":"John Bonaparte","start_time_ms":2630000,"end_time_ms":2646000,"num_slots":1,"text":"Messing around.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":2646000,"end_time_ms":2708000,"num_slots":1,"text":"<silence> I thinking on some things, trying everything. All right. Mm-hmm <affirmative>.","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":2714000,"end_time_ms":2717000,"num_slots":1,"text":"Yeah. Re","dependents":[]},{"speaker":"S3","tier":"Unknown","start_time_ms":2718000,"end_time_ms":2721000,"num_slots":1,"text":"Lre. LORE. Okay.","dependents":[]}]}')}}]);
